exercise.referenceSolution:
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Buffer {
public:
    static inline int allocations = 0;
    static inline int copies = 0;
    static inline int moves = 0;

    Buffer(std::size_t size, int fill) : size_(size), data_(new int[size]) {
        ++allocations;
        std::fill_n(data_, size_, fill);
    }
    Buffer(const Buffer &other) : size_(other.size_), data_(new int[other.size_]) {
        ++allocations;
        ++copies;
        std::copy_n(other.data_, size_, data_);
    }
    Buffer(Buffer &&other) noexcept
        : size_(std::exchange(other.size_, 0)), data_(std::exchange(other.data_, nullptr)) {
        ++moves;
    }
    Buffer &operator=(const Buffer &) = delete;
    ~Buffer() {
        delete[] data_;
    }

    long long sum() const {
        long long s = 0;
        for (std::size_t i = 0; i < size_; ++i) {
            s += data_[i];
        }
        return s;
    }

private:
    std::size_t size_;
    int *data_;
};

int main() {
    std::vector<Buffer> buffers;
    buffers.reserve(1000);
    std::string command;
    while (std::cin >> command) {
        if (command == "make") {
            std::size_t n;
            int v;
            std::cin >> n >> v;
            buffers.push_back(Buffer(n, v));
        } else if (command == "clone") {
            std::size_t i;
            std::cin >> i;
            buffers.push_back(buffers[i - 1]);
        } else if (command == "sum") {
            std::size_t i;
            std::cin >> i;
            std::println("сумма {}", buffers[i - 1].sum());
        } else {
            std::println("выделений {}, копий {}, перемещений {}", Buffer::allocations, Buffer::copies,
                         Buffer::moves);
        }
    }
    return 0;
}

