additionalExercises.referenceSolution:
#include <cstddef>
#include <iostream>
#include <map>
#include <print>
#include <string>
#include <utility>

struct Node {
    int value;
    Node *next = nullptr;
};

class List {
public:
    static inline int allocated = 0;

    List() = default;
    List(const List &other) {
        for (const Node *n = other.head_; n; n = n->next) {
            push_back(n->value);
        }
    }
    List(List &&other) noexcept
        : head_(std::exchange(other.head_, nullptr)), tail_(std::exchange(other.tail_, nullptr)),
          size_(std::exchange(other.size_, 0)) {}
    List &operator=(const List &) = delete;
    ~List() {
        while (head_) {
            delete std::exchange(head_, head_->next);
        }
    }

    void push_back(int v) {
        Node *node = new Node{v};
        ++allocated;
        if (tail_) {
            tail_->next = node;
        } else {
            head_ = node;
        }
        tail_ = node;
        ++size_;
    }

    void print(const std::string &name) const {
        std::string s;
        for (const Node *n = head_; n; n = n->next) {
            s += (s.empty() ? "" : " ") + std::to_string(n->value);
        }
        std::println("{} ({}): {}", name, size_, s.empty() ? "пусто" : s);
    }

private:
    Node *head_ = nullptr;
    Node *tail_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    std::map<std::string, List> lists;
    std::string command, a;
    while (std::cin >> command) {
        if (command == "stats") {
            std::println("узлов выделено {}", List::allocated);
            continue;
        }
        std::cin >> a;
        if (command == "make") {
            std::size_t n;
            std::cin >> n;
            lists.erase(a);
            List &list = lists.try_emplace(a).first->second;
            for (std::size_t i = 0; i < n; ++i) {
                int v;
                std::cin >> v;
                list.push_back(v);
            }
        } else if (command == "copy" || command == "move") {
            std::string from;
            std::cin >> from;
            List tmp = command == "copy" ? List(lists.at(from)) : List(std::move(lists.at(from)));
            lists.erase(a);
            lists.try_emplace(a, std::move(tmp));
        } else if (command == "push") {
            int x;
            std::cin >> x;
            lists.at(a).push_back(x);
        } else {
            lists.at(a).print(a);
        }
    }
    return 0;
}

